mapper.select:
SELECT TASK_ID, TASK_NO, TASK_NAME, INVENTORY_TYPE, ASSET_COUNT, INVENTORIED_COUNT,
       DIFFERENCE_COUNT, PROGRESS, STATUS, PLAN_DATE, RESPONSIBLE_PERSON, REMARK,
       TENANT_ID, CREATE_BY, CREATE_TIME, UPDATE_BY, UPDATE_TIME, IS_DELETED
FROM TBL_FIXED_ASSET_INVENTORY_TASK
WHERE IS_DELETED = 0

    AND TENANT_ID = #{param.tenantId}


    AND TASK_NO LIKE '%' || #{param.taskNo} || '%'


    AND TASK_NAME LIKE '%' || #{param.taskName} || '%'


    AND INVENTORY_TYPE = #{param.inventoryType}


    AND STATUS = #{param.status}


    AND PLAN_DATE >= #{param.planDateStart}


    AND PLAN_DATE <= #{param.planDateEnd}

ORDER BY PLAN_DATE DESC, CREATE_TIME DESC
